    finalOptions.env = {
      ...(finalOptions.env ?? {}),
      CONTAINERS_MACHINE_PROVIDER: getProviderByLabel(containersProvider),
    };
  }

  return extensionApi.process.exec(getPodmanCli(), args, finalOptions);
}

