31	/**
32	 * Provides access to the certificates of the underlying platform.
33	 * It supports Linux, Windows and MacOS.
34	 */
35	@injectable()
36	export class Certificates {
37	  private allCertificates: string[] = [];
38	
39	  /**
40	   * Setup all certificates globally depending on the platform.
41	   */
42	  async init(): Promise<void> {
43	    this.allCertificates = await this.retrieveCertificates();
44	
45	    // initialize the certificates globally
46	    https.globalAgent.options.ca = this.allCertificates;
47	  }
48	
49	  getAllCertificates(): string[] {
50	    return this.allCertificates;
51	  }
52	
53	  async retrieveCertificates(): Promise<string[]> {
54	    if (isMac()) {
55	      return this.retrieveMacOSCertificates();
56	    } else if (isWindows()) {
57	      return this.retrieveWindowsCertificates();
58	    } else if (isLinux()) {
59	      return this.retrieveLinuxCertificates();
60	    }
61	
62	    // else return default root certificates
63	    return [...tls.rootCertificates];
64	  }
65	
66	  public extractCertificates(content: string): string[] {
67	    // need to create an array of text from the content starting by '-----BEGIN CERTIFICATE-----'
68	    // use a regexp
69	    return content.split(/(?=-----BEGIN CERTIFICATE-----)/g).filter(c => c.trim().length > 0);
70	  }
71	
72	  async retrieveMacOSCertificates(): Promise<string[]> {
73	    const rootCertificates = await this.getMacOSCertificates(
74	      '/System/Library/Keychains/SystemRootCertificates.keychain',
75	    );
76	    const userCertificates = await this.getMacOSCertificates();
77	    return rootCertificates.concat(userCertificates);
78	  }
79	
80	  // get the certificates from the Windows certificate store
81	  async retrieveWindowsCertificates(): Promise<string[]> {
82	    // delegate to the win-ca module
83	    const winCaRetrieval = new Promise<string[]>(resolve => {
84	      const CAs: string[] = [...tls.rootCertificates];
85	
86	      if (import.meta.env.PROD) {
87	        const rootExePath = path.join(process.resourcesPath, 'win-ca', 'roots.exe');
88	        wincaAPI.exe(rootExePath);
89	      } else {
90	        wincaAPI.exe(require.resolve('win-ca/lib/roots.exe'));
91	      }
92	
93	      wincaAPI({
94	        format: wincaAPI.der2.pem,
95	        inject: false,
96	        store: ['root', 'ca'],
97	        ondata: (ca: string) => {
98	          CAs.push(ca);
99	        },
100	        onend: () => {
101	          resolve(CAs);
102	        },
103	      });
104	    });
105	
106	    try {
107	      const result = await winCaRetrieval;
108	      // also do the patch on tls.createSecureContext()
109	      wincaAPI.inject('+');
110	      return result;
111	    } catch (error) {
112	      console.error('Error while retrieving Windows certificates', error);
113	      // return default root certificates
114	      return [...tls.rootCertificates];
115	    }
116	  }
117	
118	  // grab the certificates from the Linux certificate store
119	  async retrieveLinuxCertificates(): Promise<string[]> {
120	    // certificates on Linux are stored in /etc/ssl/certs/ folder
121	    // for example
122	    // /etc/ssl/certs/ca-certificates.crt or /etc/ssl/certs/ca-bundle.crt
123	    const LINUX_FILES = ['/etc/ssl/certs/ca-certificates.crt', '/etc/ssl/certs/ca-bundle.crt'];
124	
125	    // read the files and parse the content
126	    const certificates: string[] = [];
127	    for (const file of LINUX_FILES) {
128	      // if the file exists, read it
129	      if (fs.existsSync(file)) {
130	        const content = await fs.promises.readFile(file, { encoding: 'utf8' });
131	        try {
132	          this.extractCertificates(content).forEach(certificate => certificates.push(certificate));
133	        } catch (error) {
134	          console.log(`error while extracting certificates from ${file}`, error);
135	        }
136	      }
137	    }
138	    // remove any duplicates
139	    return certificates.filter((value, index, self) => self.indexOf(value) === index);
140	  }
141	
142	  async getMacOSCertificates(key?: string): Promise<string[]> {
143	    const command = '/usr/bin/security';
144	    const spawnArgs = ['find-certificate', '-a', '-p'];
145	    // do we have an extra parameter
146	    if (key) {
147	      spawnArgs.push(key);
148	    }
149	
150	    // call the spawn command (as we've lot ot output)
151	    const spawnResult = await spawnWithPromise(command, spawnArgs);
152	    if (spawnResult.error) {
153	      console.log('error while executing command', command, spawnArgs, spawnResult.error);
154	      return [];
155	    } else {
156	      try {
157	        return this.extractCertificates(spawnResult.stdout);
158	      } catch (error) {
159	        console.log('error while extracting certificates', error);
160	        return [];
161	      }
162	    }
163	  }
164	}
